// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/orbitron";
import "@fontsource/noto-sans-kr";

export const orbitron = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { orbitron, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "CYBER GRID";

/**
 * CYBER GRID 사이버 그리드 — a cyberpunk HUD interface. The signature is a
 * perspective CSS grid floor: a repeating-linear-gradient of cyan/green lines
 * on a tilted plane (perspective + rotateX) that recedes to a vanishing point,
 * with the lines slowly scrolling toward the viewer for motion. HUD corner
 * brackets frame the hero and a repeating-linear-gradient scan-line overlay
 * sits over everything (CRT). The wordmark "CYBER GRID" is cyan with a cyan
 * glow and a red/blue chromatic offset. The pointer adds a gentle parallax to
 * the grid + brackets (input-only, lerped).
 *
 * `.cyber-grid-js` is added on mount so the no-JS markup is the finished page.
 */
export default function CyberGridPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const stageRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("cyber-grid-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "cyber-grid" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Pointer parallax — grid + HUD lean gently toward the cursor (input-only).
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage || reduced) return;
    let raf = 0;
    let tx = 0;
    let ty = 0;
    let cx = 0;
    let cy = 0;
    const onMove = (ev: PointerEvent) => {
      const r = stage.getBoundingClientRect();
      if (r.width < 4) return;
      tx = ((ev.clientX - r.left) / r.width - 0.5) * 2; // -1..1
      ty = ((ev.clientY - r.top) / r.height - 0.5) * 2;
      if (!Number.isFinite(tx) || !Number.isFinite(ty)) return;
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const tick = () => {
      cx += (tx - cx) * 0.08;
      cy += (ty - cy) * 0.08;
      stage.style.setProperty("--cg-rx", `${(cy * -4).toFixed(2)}deg`);
      stage.style.setProperty("--cg-ry", `${(cx * 6).toFixed(2)}deg`);
      if (Math.abs(tx - cx) > 0.01 || Math.abs(ty - cy) > 0.01) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
      }
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [reduced]);

  return (
    <div ref={rootRef} className={`${orbitron.variable} ${notoSansKR.variable} cyber-grid-root`}>
      <div className="cyber-grid-bg" aria-hidden="true">
        <div ref={stageRef} className="cyber-grid-floor" />
        <div className="cyber-grid-haze" />
      </div>
      <div className="cyber-grid-scan" aria-hidden="true" />

      <div ref={revealRef} className="cyber-grid-doc">
        <header className="cyber-grid-hero">
          <div className="cyber-grid-hud" aria-hidden="true">
            <span className="cyber-grid-corner cyber-grid-corner--tl" />
            <span className="cyber-grid-corner cyber-grid-corner--tr" />
            <span className="cyber-grid-corner cyber-grid-corner--bl" />
            <span className="cyber-grid-corner cyber-grid-corner--br" />
          </div>
          <p className="cyber-grid-kicker">
            <span lang="ko">사이버 그리드</span> · THE FUTURE AS HUD · 2026
          </p>
          <h1 className="cyber-grid-title" aria-label={TITLE}>
            <span className="cyber-grid-chroma" aria-hidden="true">
              {TITLE.split("").map((ch, i) => (
                <span key={i} className="cyber-grid-glyph" style={{ "--cg-i": i } as CSSProperties}>
                  {ch === " " ? "\u00A0" : ch}
                </span>
              ))}
            </span>
          </h1>
          <p className="cyber-grid-title__ko" lang="ko">사이버 그리드</p>
          <p className="cyber-grid-sub">
            <span lang="ko">HUD 미래.</span> The future as HUD.
          </p>
          <p className="cyber-grid-hint" lang="ko">SYS.ONLINE — 시스템 정상 작동 중.</p>
        </header>

        <main>
          <section className="cyber-grid-grid">
            {[
              { ko: "원근 그리드", en: "Perspective grid", n: "01" },
              { ko: "스캔라인", en: "Scan-line", n: "02" },
              { ko: "색수차 글로우", en: "Chroma glow", n: "03" },
            ].map((c, i) => (
              <article
                key={i}
                className="cyber-grid-card"
                data-reveal
                style={{ "--cg-d": i * 90 } as CSSProperties}
              >
                <span className="cyber-grid-card__n">{c.n}</span>
                <span className="cyber-grid-card__en">{c.en}</span>
                <span className="cyber-grid-card__ko" lang="ko">{c.ko}</span>
              </article>
            ))}
          </section>

          <section className="cyber-grid-lead" data-reveal>
            <p className="cyber-grid-lead__p">
              <span lang="ko">
                우리는 화면이 아니라 인터페이스를 그린다. 원근의 선이 소실점으로
                달리고, 스캔라인이 위를 흐른다 — 미래는 곧 HUD다.
              </span>{" "}
              We don't draw a screen, we draw an interface. Perspective lines run
              to the vanishing point, scan-lines flow overhead — the future is a
              HUD.
            </p>
          </section>
        </main>

        <footer className="cyber-grid-foot">
          <span>CYBER GRID · 2026</span>
          <span lang="ko">사이버 그리드 — 서울</span>
        </footer>
      </div>
    </div>
  );
}

.cyber-grid-root {
  --cg-bg: #02060a;
  --cg-deep: #010306;
  --cg-text: #d6fff4;
  --cg-mute: #5a8a82;
  --cg-cyan: #00ffc8;
  --cg-green: #39ff9e;
  --cg-red: #ff2d55;
  --cg-blue: #2d7bff;
  --cg-font-display: "Orbitron", system-ui, sans-serif;
  --cg-font-kr: "Noto Sans KR", sans-serif;
  --cg-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --cg-rx: 0deg;
  --cg-ry: 0deg;

  position: relative;
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(60% 50% at 50% 100%, rgba(0, 255, 200, 0.12), transparent 70%),
    radial-gradient(40% 40% at 50% 0%, rgba(45, 123, 255, 0.08), transparent 70%),
    var(--cg-bg);
  color: var(--cg-text);
  font-family: var(--cg-font-kr);
  font-weight: 300;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}
.cyber-grid-root ::selection { background: var(--cg-cyan); color: var(--cg-deep); }

/* ---- Perspective grid floor (the signature) ---- */
.cyber-grid-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  perspective: 320px;
  overflow: hidden;
}
.cyber-grid-floor {
  position: absolute;
  left: -50%;
  right: -50%;
  bottom: -10%;
  height: 90%;
  transform-origin: 50% 100%;
  transform: rotateX(var(--cg-rx, 72deg)) rotateZ(var(--cg-ry, 0deg));
  transition: transform 200ms linear;
  background-image:
    repeating-linear-gradient(
      to right,
      transparent 0,
      transparent calc(5% - 1px),
      rgba(0, 255, 200, 0.5) calc(5% - 1px),
      rgba(0, 255, 200, 0.5) 5%
    ),
    repeating-linear-gradient(
      to bottom,
      transparent 0,
      transparent calc(5% - 1px),
      rgba(57, 255, 158, 0.45) calc(5% - 1px),
      rgba(57, 255, 158, 0.45) 5%
    );
  /* Animate the horizontal lines toward the viewer by scrolling the vertical
     repeat. background-position on the bottom-gradient gives the motion. */
  animation: cg-scroll 6s linear infinite;
  mask-image: linear-gradient(to top, #000 0%, #000 40%, transparent 100%);
  -webkit-mask-image: linear-gradient(to top, #000 0%, #000 40%, transparent 100%);
}
@keyframes cg-scroll {
  from { background-position: 0 0, 0 0; }
  to { background-position: 0 0, 0 5%; }
}
/* A bright vanishing-point horizon glow where the lines converge. */
.cyber-grid-haze {
  position: absolute;
  left: 0; right: 0;
  bottom: 38%;
  height: 30%;
  background: radial-gradient(60% 100% at 50% 100%, rgba(0, 255, 200, 0.35), transparent 70%);
  filter: blur(20px);
}
@media (prefers-reduced-motion: reduce) {
  .cyber-grid-floor { animation: none; }
}

/* ---- CRT scan-line overlay (over everything) ---- */
.cyber-grid-scan {
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0) 0,
    rgba(0, 0, 0, 0) 2px,
    rgba(0, 20, 16, 0.32) 3px,
    rgba(0, 0, 0, 0) 4px
  );
  mix-blend-mode: multiply;
  opacity: 0.6;
}

.cyber-grid-doc {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

/* ---- Hero with HUD corner brackets ---- */
.cyber-grid-hero {
  position: relative;
  min-height: 86vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(3rem, 10vh, 7rem) clamp(1.2rem, 3vw, 2.4rem) 2rem;
}
.cyber-grid-hud { position: absolute; inset: 0; pointer-events: none; }
.cyber-grid-corner {
  position: absolute;
  width: 46px;
  height: 46px;
  border: 2px solid var(--cg-cyan);
  filter: drop-shadow(0 0 6px rgba(0, 255, 200, 0.7));
}
.cyber-grid-corner--tl { top: 0; left: 0; border-right: none; border-bottom: none; }
.cyber-grid-corner--tr { top: 0; right: 0; border-left: none; border-bottom: none; }
.cyber-grid-corner--bl { bottom: 0; left: 0; border-right: none; border-top: none; }
.cyber-grid-corner--br { bottom: 0; right: 0; border-left: none; border-top: none; }

.cyber-grid-kicker {
  margin: 0 0 1.4rem;
  font-family: var(--cg-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 500;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--cg-cyan);
}
.cyber-grid-title {
  margin: 0;
  font-family: var(--cg-font-display);
  font-weight: 900;
  font-size: clamp(2.2rem, 9vw, 7rem);
  line-height: 0.95;
  letter-spacing: 0.02em;
}
/* Chromatic wordmark: cyan fill with a cyan glow plus a red offset (right) and
   a blue offset (left) — the CRT chromatic-aberration signature. */
.cyber-grid-chroma {
  display: inline-block;
  color: var(--cg-cyan);
  text-shadow:
    2px 0 var(--cg-red),
    -2px 0 var(--cg-blue),
    0 0 10px rgba(0, 255, 200, 0.8),
    0 0 24px rgba(0, 255, 200, 0.6),
    0 0 48px rgba(0, 255, 200, 0.35);
}
.cyber-grid-glyph { display: inline-block; }
.cyber-grid-title__ko {
  margin: 0.8rem 0 0;
  font-family: var(--cg-font-kr);
  font-weight: 300;
  font-size: clamp(1rem, 2.4vw, 1.6rem);
  letter-spacing: 0.42em;
  color: var(--cg-mute);
}
.cyber-grid-sub {
  margin: 1.6rem 0 0.4rem;
  font-family: var(--cg-font-display);
  font-size: clamp(1rem, 1.8vw, 1.3rem);
  font-weight: 500;
}
.cyber-grid-sub span[lang="ko"] { color: var(--cg-mute); margin-right: 0.5rem; }
.cyber-grid-hint {
  margin: 0;
  font-family: var(--cg-font-display);
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  color: var(--cg-green);
  text-shadow: 0 0 8px rgba(57, 255, 158, 0.5);
}

/* ---- Grid cards (HUD panels) ---- */
.cyber-grid-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(0.9rem, 1.6vw, 1.3rem);
  padding: clamp(1rem, 3vw, 2rem) 0;
}
.cyber-grid-card {
  position: relative;
  padding: clamp(1.2rem, 2.4vw, 1.8rem);
  border-radius: 4px;
  min-height: 160px;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  justify-content: flex-end;
  background:
    linear-gradient(135deg, rgba(0, 255, 200, 0.08), rgba(57, 255, 158, 0.05)),
    rgba(2, 12, 16, 0.6);
  border: 1px solid rgba(0, 255, 200, 0.35);
  box-shadow: inset 0 0 18px rgba(0, 255, 200, 0.08), 0 0 24px -8px rgba(0, 255, 200, 0.25);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.cyber-grid-card__n { font-family: var(--cg-font-display); font-weight: 700; font-size: 0.78rem; color: var(--cg-cyan); letter-spacing: 0.2em; text-shadow: 0 0 8px rgba(0,255,200,0.5); }
.cyber-grid-card__en { font-family: var(--cg-font-display); font-weight: 500; font-size: 1.1rem; }
.cyber-grid-card__ko { font-size: 0.88rem; color: var(--cg-mute); }

.cyber-grid-lead {
  padding: clamp(2.5rem, 6vw, 4rem) 0;
  border-top: 1px solid rgba(0, 255, 200, 0.2);
}
.cyber-grid-lead__p {
  margin: 0 auto;
  max-width: 62ch;
  font-family: var(--cg-font-display);
  font-weight: 300;
  font-size: clamp(1.05rem, 2.2vw, 1.55rem);
  line-height: 1.5;
  text-align: center;
}
.cyber-grid-lead__p span[lang="ko"] {
  display: block;
  font-family: var(--cg-font-kr);
  color: var(--cg-mute);
  font-size: 0.78em;
  margin-bottom: 0.6em;
}

.cyber-grid-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(2rem, 5vw, 3rem) 0;
  border-top: 1px solid rgba(0, 255, 200, 0.2);
  font-family: var(--cg-font-display);
  font-size: 0.74rem;
  letter-spacing: 0.18em;
  color: var(--cg-mute);
}

/* ---- Reveal gating ---- */
.cyber-grid-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--cg-ease), transform 800ms var(--cg-ease);
  transition-delay: calc(var(--cg-d, 0) * 1ms);
}
.cyber-grid-js [data-reveal].is-visible { opacity: 1; transform: none; }
.cyber-grid-js .cyber-grid-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  display: inline-block;
  transition: opacity 700ms var(--cg-ease), transform 700ms var(--cg-ease);
  transition-delay: calc(var(--cg-i) * 70ms + 150ms);
}
.cyber-grid-js.is-mounted .cyber-grid-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .cyber-grid-js [data-reveal], .cyber-grid-js .cyber-grid-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important;
  }
}
.cyber-grid-root :focus-visible { outline: 2px solid var(--cg-cyan); outline-offset: 3px; }
